export const LANVAC_DISPATCH_CITIES = Object.keys(LANVAC_EMERGENCY_NUMBERS);

const FREQUENT = new Set<string>(LANVAC_DISPATCH_CITIES_FREQUENT);

export function lanvacEmergencyNumbers(city: string | null | undefined): LanvacEmergencyNumbers | null {
  if (!city?.trim()) return null;
  return LANVAC_EMERGENCY_NUMBERS[city.trim()] ?? null;
}

export function isLanvacDirectoryCity(city: string): boolean {
  return city.trim() in LANVAC_EMERGENCY_NUMBERS;
}

export function lanvacCitySelectOptions(current?: string | null): {
  frequent: string[];
  other: string[];
  extra: string | null;
} {
  const extra = current?.trim() && !(current.trim() in LANVAC_EMERGENCY_NUMBERS) ? current.trim() : null;
  return {
    frequent: [...LANVAC_DISPATCH_CITIES_FREQUENT],
    other: LANVAC_DISPATCH_CITIES.filter((city) => !FREQUENT.has(city)),
    extra,
  };
}

const TOWN_GUESSES = LANVAC_DISPATCH_CITIES_FREQUENT.map((city) => ({
  city,
  needle: city.split(/[-,]/)[0].trim().toLowerCase(),
}))
  .filter((row) => row.needle.length >= 4)
  .sort((a, b) => b.needle.length - a.needle.length);

export function guessLanvacCityFromAddress(address: string): string | null {
  const hay = address.toLowerCase();
  if (!hay.trim()) return null;
  for (const row of TOWN_GUESSES) {
    if (hay.includes(row.needle)) return row.city;
  }
  return null;
}

